# katalog pesan aicrew, Indonesia (pilihan). Satu cabang `case` per kunci; argumen adalah $2.. setelah kunci.
msg_id() {
  local k="$1"; shift
  case "$k" in
    lang.selftest) printf 'bahasa: Indonesia' ;;
    lang.args) printf 'dua argumen: %s dan %s' "$@" ;;
    gate.repo_unknown) printf 'repo tak dapat ditentukan' ;;
    gate.pr_unreadable) printf 'PR #%s tak terbaca (REST)' "$@" ;;
    gate.not_merged) printf 'PR #%s belum MERGED (%s)' "$@" ;;
    gate.merged_in_dst) printf 'PR #%s (%s) ada di %s' "$@" ;;
    gate.merged_not_in_dst) printf 'PR #%s ter-merge tetapi %s tidak ada di %s' "$@" ;;
    gate.pr_base) printf 'PR #%s basis: %s' "$@" ;;
    gate.multi_close_kw) printf 'satu kata kunci hanya menutup satu issue; tulis satu '\''Closes #n'\'' per baris' ;;
    gate.base_mismatch) printf 'basis %s != %s; jalankan: gh pr edit %s --base %s' "$@" ;;
    gate.head_unreadable) printf 'head PR #%s tak terbaca' "$@" ;;
    gate.pr_labels_unreadable) printf 'label PR #%s tak terbaca' "$@" ;;
    gate.timeline_unreadable) printf 'timeline PR #%s tak terbaca (REST); closingIssuesReferences tak dapat diperiksa saat GraphQL habis' "$@" ;;
    gate.sidebar_link_gql_exhausted) printf 'PR #%s punya tautan sidebar (Development) yang tak dapat diurai lewat REST saat GraphQL habis; tunggu reset lalu ulangi' "$@" ;;
    gate.cross_ref_gql_exhausted) printf 'PR #%s menutup issue lewat URL atau owner/repo#N yang tak dapat diperiksa saat GraphQL habis; tunggu reset lalu ulangi' "$@" ;;
    gate.gql_exhausted_body_fallback) printf 'GraphQL habis; issue yang ditutup PR dibaca dari semua #N di badan PR (tanpa tautan sidebar)' ;;
    gate.closing_refs_unreadable) printf 'closingIssuesReferences PR #%s tak terbaca' "$@" ;;
    gate.issue_labels_unreadable) printf 'label issue #%s tak terbaca' "$@" ;;
    gate.issue_body_unreadable) printf 'body of issue #%s could not be read' "$@" ;;
    gate.owner_only_auto) printf 'PR closes issue(s)%s whose criteria are marked owner only; write Refs #N instead of Closes #N, or let the owner merge' "$@" ;;
    gate.owner_only_warn) printf 'PR closes issue(s)%s whose criteria are marked owner only; the owner follow-up is lost when the issue closes' "$@" ;;
    gate.pr_branch_unreadable) printf 'PR branch could not be read' ;;
    gate.hold_branch_labels_unreadable) printf 'owner-hold: issue #%s labels could not be read (REST)' "$@" ;;
    gate.hold_branch_issue) printf 'owner-hold: issue #%s is held by the owner' "$@" ;;
    gate.hold_pr) printf 'owner-hold: automatic merge requires the owner to release the hold' ;;
    gate.invalid_dst_branch) printf 'cabang tujuan '\''%s'\'' berkarakter tidak sah' "$@" ;;
    gate.pr_files_unreadable) printf 'daftar file PR #%s tak terbaca' "$@" ;;
    gate.pr_files_unparseable) printf 'daftar file PR #%s tak terurai' "$@" ;;
    gate.pr_files_accumulate) printf 'PR files could not be accumulated' ;;
    gate.touches_workflow) printf 'PR menyentuh docs/WORKFLOW.md; auto-merge ditolak (izin sementara hanya dari owner); minta owner merge' ;;
    gate.too_many_files) printf 'PR punya lebih dari 3000 file; auto-merge ditolak' ;;
    gate.l2_default_branch_unreadable) printf 'risk:L2: auto-merge ditolak; cabang bawaan tak terbaca (izin tidak dievaluasi)' ;;
    gate.l2_workflow_unreadable) printf 'risk:L2: auto-merge ditolak; docs/WORKFLOW.md tak terbaca di %s (izin tidak dievaluasi)' "$@" ;;
    gate.l2_no_grant) printf 'risk:L2: auto-merge ditolak; minta owner merge (tidak ada izin sementara yang sah dan belum kedaluwarsa untuk %s)' "$@" ;;
    gate.temp_grant) printf 'izin sementara: %s (merge sebelum expires di atas; jalankan gerbang ulang tepat sebelum merge)' "$@" ;;
    gate.compare_failed) printf 'PR tertinggal dari %s tak dapat diperiksa (compare REST gagal; PR dari fork tidak di-merge otomatis)' "$@" ;;
    gate.behind_by_unreadable) printf 'behind_by dari compare %s...%s tak terbaca' "$@" ;;
    gate.pr_behind) printf 'PR tertinggal %s commit dari %s; perbarui cabang (merge %s ke cabang PR) lalu tunggu CI untuk head baru; CI hijau pada head lama tidak membuktikan hasil merge' "$@" ;;
    gate.check_runs_unreadable) printf 'check-run CI untuk head %s tak terbaca (REST)' "$@" ;;
    gate.unnamed_check_run) printf 'ada check-run CI tanpa nama untuk head %s; tak dapat dinilai' "$@" ;;
    gate.workflow_runs_unreadable) printf 'workflow run untuk head %s tak terbaca (REST)' "$@" ;;
    gate.open_runs_count_unreadable) printf 'jumlah workflow run belum selesai untuk head %s tak terbaca' "$@" ;;
    gate.ci_runs_in_progress) printf 'CI belum selesai untuk head %s (%s workflow run masih berjalan); tunggu lalu ulangi' "$@" ;;
    gate.workflows_unreadable) printf 'daftar workflow tak terbaca (CI belum dapat dipastikan)' ;;
    gate.workflows_total_unreadable) printf 'total workflow tak terbaca (CI belum dapat dipastikan)' ;;
    gate.ci_not_started) printf 'CI belum mulai untuk head %s (%s workflow terdaftar, belum ada check-run); tunggu lalu ulangi' "$@" ;;
    gate.ci_classify_failed) printf 'klasifikasi CI untuk head %s gagal' "$@" ;;
    gate.ci_non_green_conclusion) printf 'CI untuk head %s punya check dengan hasil yang belum dapat dianggap hijau (mis. action_required atau stale)' "$@" ;;
    gate.ci_no_successful_check) printf 'CI untuk head %s tidak punya check yang berhasil (semua dilewati atau netral)' "$@" ;;
    gate.ci_pending) printf 'CI belum selesai untuk head %s; tunggu lalu ulangi' "$@" ;;
    gate.ci_infra_prefix) printf 'CI tidak dapat mulai (infrastruktur, bukan kegagalan kode): %s' "$@" ;;
    gate.ci_infra_mixed_checks) printf '%s; ada check lain yang belum selesai, dibatalkan, perlu tindakan, atau gagal dari app selain GitHub Actions: suite lokal tidak dapat menggantikan CI' "$@" ;;
    gate.ci_failed) printf 'CI gagal untuk head %s' "$@" ;;
    gate.ci_classify_unknown) printf 'klasifikasi CI untuk head %s tak dikenal' "$@" ;;
    gate.pr_behind_warn) printf 'PR tertinggal %s commit dari %s; CI pada head ini tidak menguji hasil merge ke %s terkini' "$@" ;;
    gate.pr_comments_unreadable) printf 'komentar PR #%s tak terbaca (REST)' "$@" ;;
    gate.test_approval_eval_failed) printf 'Owner test-change approvals could not be evaluated' ;;
    gate.test_approval_required) printf 'Existing test changes require approval: %s\nOwner approval (scope: test-change <path>[, <path>...]): <text> (Commit: <sha>)' "$@" ;;
    gate.ci_infra_default_branch_unreadable) printf '%s; cabang bawaan tak terbaca (izin ci-local tidak dievaluasi)' "$@" ;;
    gate.ci_infra_workflow_unreadable) printf '%s; docs/WORKFLOW.md tak terbaca di %s (izin ci-local tidak dievaluasi)' "$@" ;;
    gate.ci_infra_no_replacement) printf '%s; perbaiki akun/runner lalu ulangi, atau owner menulis izin '\''- Grant: scope=ci-local; branch=%s; expires=...'\'' di WORKFLOW.md %s DAN komentar '\''Laporan ci-lokal: lulus Commit: <sha head>'\'' (suite penuh lokal untuk head ini)' "$@" ;;
    gate.ci_replaced_by_local) printf 'CI digantikan suite lokal untuk head %s (izin: %s); CI tidak membuktikan hasil ini' "$@" ;;
    gate.needs_security) printf 'needs-security: butuh komentar '\''Laporan security: lulus'\'' dengan '\''Commit: <sha head>'\'' dari aicrew-security, ditulis oleh OWNER/MEMBER/COLLABORATOR (dua baris, atau satu baris: '\''Laporan security: lulus Commit: <sha head>'\''; huruf besar/kecil bebas)' ;;
    gate.needs_perf) printf 'needs-perf: butuh '\''Laporan perf: lulus'\'' dengan Angka sebelum/sesudah (berdigit), Tuning, dan '\''Commit: <sha head>'\'' dari aicrew-perf, atau waiver owner untuk head' ;;
    gate.needs_qa) printf 'PR bukan dokumentasi saja: butuh komentar '\''Laporan qa: lulus'\'' dari aicrew-qa dengan '\''Commit: <sha head>'\'' (dua baris, atau satu baris: '\''Laporan qa: lulus Commit: <sha head>'\''; huruf besar/kecil bebas); vonis terakhir untuk head menang' ;;
    gate.issue_comments_unreadable) printf 'komentar issue #%s tak terbaca (REST); keputusan owner tak dapat diperiksa' "$@" ;;
    gate.issue_comments_unparseable) printf 'komentar issue #%s tak terurai' "$@" ;;
    gate.owner_decision_eval_failed) printf 'keputusan owner tak dapat dievaluasi' ;;
    gate.owner_decision_pending) printf 'keputusan owner setelah vonis terakhir untuk head belum diakui: %s; terapkan, lalu penulis PR menulis komentar '\''Decision applied: <ringkasan>'\'' (dan vonis baru bila head berubah)' "$@" ;;
    gate.diff_unreadable) printf 'diff PR #%s tak terbaca (REST)' "$@" ;;
    gate.baseline_secret) printf 'baseline-scan menemukan rahasia pada diff; perbaiki, atau waiver owner (rahasia) untuk head PR' ;;
    gate.cve_repo_unknown) printf 'cve: repo tak dapat ditentukan' ;;
    gate.cve_files_unreadable) printf 'cve: daftar berkas PR #%s tak terbaca (REST)' "$@" ;;
    gate.cve_workflow_unreadable) printf 'cve: docs/WORKFLOW.md tak terbaca di cabang tujuan (REST); pola paket privat tak diketahui' ;;
    gate.cve_disabled) printf 'pemeriksaan CVE dimatikan di WORKFLOW.md' ;;
    gate.cve_manifest_missing_head) printf 'cve: %s tidak ditemukan di head (REST) padahal tidak dihapus' "$@" ;;
    gate.cve_manifest_unreadable_head) printf 'cve: %s tak terbaca di head (REST)' "$@" ;;
    gate.cve_manifest_unreadable_base) printf 'cve: %s tak terbaca di merge-base (REST)' "$@" ;;
    gate.cve_npmrc_unreadable) printf 'cve: %s tak terbaca di cabang tujuan (REST); pola paket privat tak diketahui' "$@" ;;
    gate.cve_new_private_pattern) printf 'cve (%s) pola privat baru baru berlaku setelah di-merge; paket yang cocok pada PR ini tetap dikirim' "$@" ;;
    gate.cve_private_skipped) printf 'cve (%s) %s paket privat tidak diperiksa' "$@" ;;
    gate.cve_new_vuln) printf 'cve: kerentanan HIGH/CRITICAL/UNKNOWN baru pada dependensi; naikkan sesuai saran di atas, atau waiver owner (cve) untuk head PR' ;;
    gate.cve_osv_unreachable) printf 'cve: OSV tidak terjangkau untuk PR yang menyentuh manifest; ulangi nanti, atau waiver owner (cve) untuk head PR' ;;
    gate.sched_check_failed) printf 'alur terjadwal tidak dapat diperiksa' ;;
    gate.sched_default_branch_unreadable) printf 'alur terjadwal tidak dapat diperiksa (cabang bawaan tak terbaca)' ;;
    gate.sched_inactive_until_default) printf 'alur terjadwal %s tidak aktif sampai ada di cabang bawaan (%s)' "$@" ;;
    gate.missing_release_note) printf 'PR tanpa baris '\''Release note:'\'' (docs/WORKFLOW.md di %s memakai CHANGELOG.md); tulis '\''Release note: <Added|Changed|Fixed|Security> - <teks>'\'' atau '\''Release note: -'\'' bila internal' "$@" ;;
    gate.passed) printf 'gerbang lolos untuk head %s. Merge dengan: gh pr merge %s --match-head-commit %s' "$@" ;;
    autopilot.unknown_arg) printf 'argumen tak dikenal: %s' "$@" ;;
    autopilot.already_running) printf 'autopilot already running (pid %s, started %s)' "$@" ;;
    autopilot.lock_failed) printf 'autopilot: cannot take lock %s' "$@" ;;
    autopilot.last_completed) printf 'putaran %s: terakhir selesai: #%s (%s)' "$@" ;;
    autopilot.round_summary) printf 'putaran %s: ringkasan: durasi %ss; rc=%s; PR digabung: %s; PR terbuka: %s; total %s' "$@" ;;
    autopilot.round_summary_gh_err) printf 'putaran %s: ringkasan: durasi %ss; rc=%s; PR tak terbaca (gh gagal); total %s' "$@" ;;
    autopilot.owner_actions_suffix) printf '; tindakan owner: %s' "$@" ;;
    autopilot.board_sync_failed) printf 'board: --sync gagal (diabaikan)' ;;
    autopilot.board_sync_cards_failed) printf 'board: --sync-cards gagal (diabaikan)' ;;
    autopilot.no_session_persistence) printf 'putaran %s: --no-session-persistence di AICREW_CLAUDE_ARGS (transkrip tidak ditulis); watchdog idle tidak aktif untuk putaran ini, --round-timeout tetap berlaku' "$@" ;;
    autopilot.transcript_dir_missing) printf 'putaran %s: direktori transkrip tidak ditemukan (%s); watchdog idle tidak aktif untuk putaran ini' "$@" ;;
    autopilot.reason_round_timeout) printf 'batas waktu putaran (%s detik)' "$@" ;;
    autopilot.reason_idle) printf 'idle %s menit' "$@" ;;
    autopilot.interrupted_sigint) printf 'putaran %s: %s; diinterupsi (SIGINT)' "$@" ;;
    autopilot.still_alive_after_sigint) printf 'putaran %s: sesi masih hidup %s detik setelah SIGINT; menunggu %s detik lagi' "$@" ;;
    autopilot.sent_sigterm) printf 'putaran %s: sesi tidak berakhir; dikirim SIGTERM' "$@" ;;
    autopilot.still_stuck) printf 'autopilot: masih buntu: state unchanged since %s; changed inputs: none; tidak ada putaran dijalankan (ubah issue/PR, WORKFLOW.md atau berkas izin, atau pakai --retry-stuck)' "$@" ;;
    autopilot.gh_unreadable_retry) printf 'putaran %s: gh tidak terbaca (percobaan %s/5): keadaan tidak diketahui, tidak memutuskan selesai atau menunggu' "$@" ;;
    autopilot.gh_down_stop) printf 'autopilot: gh tidak terbaca 5 kali beruntun; berhenti (bukan keadaan issue), periksa jaringan dan login gh' ;;
    autopilot.all_done) printf 'autopilot: semua issue selesai (putaran %s)' "$@" ;;
    autopilot.all_await_owner) printf 'autopilot: all %s remaining issues await the owner (needs-principal, blocked or owner-hold)' "$@" ;;
    autopilot.max_total_reached) printf 'autopilot: %s; total kumulatif antar-jalan, nolkan dengan --reset-total atau hapus .aicrew/total' "$@" ;;
    autopilot.waiting_owner) printf 'autopilot: waiting for owner (%s issues: needs-principal, blocked, owner-hold or an open PR awaiting merge); check every %s minutes, limit %s days' "$@" ;;
    autopilot.wait_timeout) printf 'autopilot: menunggu owner melewati batas %s hari; berhenti' "$@" ;;
    autopilot.wait_resumed) printf 'autopilot: ada perubahan saat menunggu (mis. merge oleh owner); lanjut putaran' ;;
    autopilot.round_start) printf 'putaran %s: %s issue terbuka (%s waiting for owner)' "$@" ;;
    autopilot.in_progress) printf 'putaran %s: sedang dikerjakan: %s' "$@" ;;
    autopilot.round_rc) printf 'putaran %s: rc=%s' "$@" ;;
    autopilot.watchdog_ended) printf 'putaran %s: diakhiri watchdog idle (rc dinormalkan); daftar issue dimuat ulang di putaran berikut' "$@" ;;
    autopilot.limit_wait) printf 'autopilot: kena limit, menunggu %s menit lalu coba lagi' "$@" ;;
    autopilot.limit_false_positive) printf 'putaran %s: keluaran menyebut kata limit tetapi rc=0 dan laporan panjang (%s baris); dianggap normal (bukan limit)' "$@" ;;
    autopilot.limit_resumed) printf 'autopilot: lanjut setelah limit' ;;
    autopilot.round_failed) printf 'putaran %s: gagal rc=%s (%s berturut-turut), lihat %s' "$@" ;;
    autopilot.consecutive_failures) printf 'autopilot: 3 putaran gagal beruntun (rc=%s); berhenti, lihat %s' "$@" ;;
    autopilot.stuck) printf 'autopilot: buntu, %s putaran tanpa perubahan di issue/PR; berhenti' "$@" ;;
    autopilot.fingerprint_unreadable) printf 'putaran %s: sidik jari tak terbaca (gh gagal); tidak dihitung maju atau buntu; jeda sebelum putaran berikutnya' "$@" ;;
    autopilot.max_rounds_reached) printf 'autopilot: batas putaran (%s) tercapai' "$@" ;;
    autostart.usage) printf 'pakai: autostart.sh install|uninstall|status|resume|run <repo> [opsi]' ;;
    autostart.dir_missing) printf 'folder tidak ada: %s' "$@" ;;
    autostart.unknown_arg) printf 'argumen tak dikenal: %s' "$@" ;;
    autostart.max_total_required) printf 'install: --max-total N (bilangan > 0) wajib, sebagai batas biaya loop tanpa pengawasan' ;;
    autostart.interval_min) printf 'install: --interval minimal 60 detik' ;;
    autostart.not_git_repo) printf 'install: %s bukan repo git' "$@" ;;
    autostart.permissions_missing) printf 'install: izin autopilot belum terpasang di %s/.claude/settings.local.json; jalankan dulu (di folder project): bash %s/install-permissions.sh' "$@" ;;
    autostart.bin_missing) printf 'install: '\''%s'\'' tidak ditemukan di PATH' "$@" ;;
    autostart.invalid_plist) printf 'install: plist tidak valid' ;;
    autostart.bootstrap_failed) printf 'install: launchctl bootstrap gagal (plist di %s)' "$@" ;;
    autostart.installed) printf 'autostart: terpasang %s (tiap %s menit dan saat login; --max-total %s). Rem: touch %s/PAUSE. Lepas: autostart.sh uninstall %s' "$@" ;;
    autostart.uninstalled) printf 'autostart: dicopot %s (state di %s dibiarkan)' "$@" ;;
    autostart.status_label) printf 'label: %s' "$@" ;;
    autostart.status_installed_yes) printf 'terpasang: ya (%s)' "$@" ;;
    autostart.status_installed_no) printf 'terpasang: tidak' ;;
    autostart.status_loaded_yes) printf 'dimuat di launchd: ya' ;;
    autostart.status_loaded_no) printf 'dimuat di launchd: tidak' ;;
    autostart.status_halted_yes) printf 'halted: ya (%s); periksa lalu: autostart.sh resume %s' "$@" ;;
    autostart.status_halted_no) printf 'halted: tidak' ;;
    autostart.status_pause_yes) printf 'PAUSE: ya' ;;
    autostart.status_pause_no) printf 'PAUSE: tidak' ;;
    autostart.status_lock_pid) printf 'kunci: pid %s' "$@" ;;
    autostart.status_lock_none) printf 'kunci: tidak ada' ;;
    autostart.status_last_log) printf 'log terakhir:' ;;
    autostart.resumed) printf 'autostart: halted dan penanda buntu dihapus; tick berikutnya menjalankan autopilot lagi' ;;
    autostart.pause_skipped) printf 'PAUSE: dilewati' ;;
    autostart.max_total_empty) printf 'AICREW_MAX_TOTAL kosong: ditolak (tanpa batas biaya)' ;;
    autostart.gh_unavailable) printf 'gh/jaringan tidak tersedia: dilewati' ;;
    autostart.already_running) printf 'autopilot lain berjalan (pid %s): dilewati' "$@" ;;
    autostart.lock_failed) printf 'gagal mengambil kunci' ;;
    autostart.starting) printf 'mulai autopilot (--max-total %s)' "$@" ;;
    autostart.finished) printf 'autopilot selesai rc=%s' "$@" ;;
    autostart.halted_notify) printf 'autostart %s: berhenti (rc=%s), tidak dijalankan lagi otomatis. Periksa %s/autopilot.log lalu: autostart.sh resume %s' "$@" ;;
    autostart.unknown_cmd) printf 'perintah tak dikenal: %s' "$@" ;;
    owner.needs_principal) printf '#%s %s — answer the question in the issue, then remove the label — `gh issue edit %s --remove-label needs-principal` — an owner decision; an agent must not decide it' "$@" ;;
    owner.owner_hold) printf '#%s %s — owner-hold: only the owner may release this hold — `gh issue edit %s --remove-label owner-hold`' "$@" ;;
    owner.blocked) printf '%s blocked: %s — resolve the cause, then remove the label — `gh issue edit %s --remove-label blocked`' "$@" ;;
    owner.pr_merge) printf 'PR #%s (issue #%s) %s — review and merge — `gh pr merge %s --merge --match-head-commit %s` — %s' "$@" ;;
    owner.reason_l2) printf 'risk:L2 is never merged automatically' ;;
    owner.reason_security) printf 'security review is pending' ;;
    owner.reason_merge_mode) printf 'the merge mode needs the owner' ;;
    owner.header) printf '# Owner actions (%s)' "$@" ;;
    owner.agent_note) printf 'agent note: %s' "$@" ;;
    owner.ci_infra) printf 'PR #%s — %s' "$@" ;;
    owner.none) printf 'No owner actions found.' ;;
    owner.summary) printf '%s (%s item)' "$@" ;;
    budget.max_iter) printf 'STOP: batas iterasi (%s) tercapai' "$@" ;;
    budget.max_fail) printf 'STOP: issue %s gagal %s kali' "$@" ;;
    budget.max_total) printf 'STOP: total %s >= %s (--max-total)' "$@" ;;
    budget.continue) printf 'lanjut' ;;
    budget.usage) printf 'pakai: budget.sh iter|newrun|fail N|reset N|check maxIter maxFail [N] [maxTotal]' ;;
    notify.default) printf 'butuh perhatian' ;;
    blocked.mark_usage) printf 'usage: blocked-mark.sh <issue-number> <reason>' ;;
    blocked.cannot_read) printf 'blocked-mark: cannot read #%s' "$@" ;;
    blocked.already) printf '#%s already blocked' "$@" ;;
    blocked.label_desc) printf 'cannot advance without outside action' ;;
    blocked.marked) printf '#%s marked blocked' "$@" ;;
    blocked.note_usage) printf 'usage: blocked-note.sh <pr> <command>' ;;
    blocked.note_allow_hint) printf 'Add to permissions.allow in .claude/settings.local.json: "Bash(%s:*)"' "$@" ;;
    *) return 1 ;;
  esac
}
